Method.Implementation:
	#dim tSC As %Status=$$$OK
	$$$TRACE("Inside Method processHttpsPostRequest")

	Set httprequest=##class(%Net.HttpRequest).%New()
	set pid=$piece(pRequest.StringValue,"|",1)
	set data=$piece(pRequest.StringValue,"|",2)
	$$$TRACE("Json String: "_data)
	//set param="/"_$Replace(recId," ","%20")
	Set httprequest.ContentType="application/json"
	set httprequest.AcceptGzip="gzip, deflate, br"
	set httprequest.AuthenticationErrors="SELF_SIGNED_CERT_IN_CHAIN"
	//set url = ..Adapter.URL_param
	if pid'="0" {
		set url = ..Adapter.URL_"/providerid="_pid_",o=corpprv,o=sources"
	}
	else {
		set url = ..Adapter.URL
	}
	$$$TRACE("URL: "_url)
	Set httprequest.Location = url
    Set dataStream=##class(%Stream.GlobalCharacter).%New()
    Do dataStream.Write(data)
    Do dataStream.Rewind()
    Do httprequest.EntityBody.Write()
	do httprequest.EntityBody.CopyFrom(dataStream)
	set cl = httprequest.ContentLengthGet()
	$$$TRACE("Content length: "_cl)
	Set httprequest.Authorization="Basic "_..credential
	$$$TRACE("Location: "_httprequest.Location)
	Set httprequest.SSLConfiguration = ..Adapter.SSLConfig
	#dim tHttpResponse As %Net.HttpResponse
    if pid="0" {
	   set tSC = httprequest.Post(url)
    }
    else {
	   set tSC = httprequest.Patch(url)
    }
	if $$$ISERR(tSC) {
         do $system.OBJ.DisplayError()
         Quit tSC
    } else {
        set tHttpResponse=httprequest.HttpResponse 
        Quit ..constructResponse(tHttpResponse, .pResponse) 
    }            
  quit tSC
